update pages set contenu = '{"sections":[]}'::jsonb where path = '/expertises/specialisations-constructeur/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Automaticien industriel multimarques","mecanisme":"Un automaticien qui arrive avec le bon atelier logiciel déjà installé, pour la marque qui est en défaut chez vous. Siemens, Schneider Electric, Allen Bradley, robotique, machines spéciales et commande numérique, y compris les versions anciennes encore en service.","cta":"Demander une intervention","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7."},{"type":"chiffres","chiffres":[{"valeur":"10 %","libelle":"des candidats retenus, après entretien technique ET comportemental"},{"valeur":"24/24 et 7/7","libelle":"astreinte, pour les sites couverts"},{"valeur":"+ 80","libelle":"clients réguliers, la plupart arrivés par une panne"}]},{"type":"probleme","punchline":"Votre parc mélange trois marques d''automates, et la seule personne capable de lire le code est en congés.","puces":[{"accroche":"Un généraliste découvre votre marque sur place.","texte":"Il ouvre le logiciel pour la première fois pendant que la ligne attend. Les heures perdues sont des heures de production."},{"accroche":"Chaque constructeur a ses pièges.","texte":"Logiciel propriétaire, langages, versions incompatibles entre elles. Ce qui marche sur un Modicon ne se transpose pas sur un S7."},{"accroche":"Le programme n''a jamais été sauvegardé.","texte":"La carte lâche, et il n''existe aucune version à jour du code à recharger."},{"accroche":"L''automate est annoncé en fin de vie.","texte":"Pièces introuvables, et personne n''a préparé la migration. Elle se fera donc en urgence, au pire moment."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Siemens, du diagnostic à la reprise de code","texte":"SIMATIC S7-300, S7-400, S7-1200 et S7-1500, TIA Portal, STEP 7, supervision WinCC."},"benefice":"Le technicien ouvre votre projet dès son arrivée au lieu de chercher la bonne version du logiciel."},{"prestation":{"accroche":"Schneider Electric sur toute la gamme","texte":"Modicon M221 à M580, Unity Pro, EcoStruxure, Zelio."},"benefice":"Un seul prestataire couvre le petit relais programmable et l''automate de sécurité de la ligne."},{"prestation":{"accroche":"Rockwell Automation","texte":"les gammes Allen Bradley rencontrées chez nos clients, en agroalimentaire."},"benefice":"Plus besoin de faire venir un spécialiste d''une autre région pour cette partie du parc."},{"prestation":{"accroche":"Robotique industrielle","texte":"cellules robotisées, axes pilotés, dialogue entre le contrôleur de ligne et le robot."},"benefice":"La cause est trouvée même quand elle est en dehors du bras, dans l''automate ou le réseau."},{"prestation":{"accroche":"Machines spéciales et commande numérique","texte":"conditionnement, assemblage, usinage, manutention, des équipements souvent uniques et peu documentés."},"benefice":"Vos machines sans documentation cessent d''être des zones que personne n''ose toucher."},{"prestation":{"accroche":"Les ateliers logiciels anciens toujours maîtrisés","texte":", y compris les versions encore en service dans l''industrie française."},"benefice":"Votre automate le plus ancien se dépanne au lieu de se remplacer en catastrophe."},{"prestation":{"accroche":"Vos automatismes sauvegardés et datés","texte":"API, variateurs, pupitres, chaque version archivée."},"benefice":"Le jour où une carte lâche, on recharge au lieu de tout réécrire."},{"prestation":{"accroche":"L''obsolescence traitée en projet","texte":"étude, conception, reprogrammation, essais, chiffrés en parallèle du maintien de l''existant."},"benefice":"Vous décidez de migrer avec les coûts sous les yeux, pas sous la pression d''une panne."},{"prestation":{"accroche":"Vos standards internes respectés","texte":"nous pouvons travailler avec votre intégrateur et vos règles de nommage plutôt que d''imposer les nôtres."},"benefice":"Votre équipe relit le code après notre passage sans avoir à réapprendre une convention."}],"prose":[{"texte":"Une marque précise à traiter ? Voyez [automaticien Siemens](/expertises/automatisme/siemens/) ou [automate Schneider](/expertises/automatisme/schneider/). Pour reprendre et documenter un code existant, la page [programmation automate](/expertises/automatisme/programmation-automate/) détaille la méthode. Un équipement immobilisé maintenant se traite par le [dépannage industriel](/offres/depannage-industriel/)."}]},{"type":"deroule","etapes":[{"titre":"Vous décrivez la panne","texte":"marque, référence de l''automate, message affiché, moment du cycle. Quelques minutes au téléphone évitent un déplacement pour rien."},{"titre":"Un technicien vous rappelle dans l''heure.","texte":"Vous savez rapidement si nous avons l''automaticien de cette marque, et lequel."},{"titre":"L''automaticien arrive équipé","texte":"ordinateur portable, câbles, licence et version du logiciel constructeur correspondant à votre installation."},{"titre":"Nous cherchons la cause racine","texte":"lecture du code, test des capteurs, contrôle des actionneurs, mesure des signaux, état du réseau de terrain."},{"titre":"Nous réparons et remettons en service","texte":"composant remplacé, sauvegarde rechargée, essais avec vos opérateurs jusqu''au retour à la cadence."},{"titre":"Vous recevez la trace écrite","texte":"code sauvegardé et daté, schéma corrigé, cause identifiée, points à surveiller au prochain passage."}]},{"type":"garanties","puces":[{"accroche":"Le rappel dans l''heure, du lundi au vendredi de 8h00 à 18h30.","texte":"L''astreinte 24/24 et 7/7 couvre la nuit et le week-end sur les sites concernés."},{"accroche":"Vos codes, vos recettes et vos données restent chez vous.","texte":"La confidentialité figure au contrat, elle ne repose pas sur des bonnes intentions."},{"accroche":"La sécurité tracée avant l''intervention","texte":"habilitations électriques à jour, démarche MASE, évaluation EcoVadis. Les attestations sont transmises avec chaque plan de prévention."}]},{"type":"cta","question":"Besoin d''un automaticien qui connaisse déjà la marque installée chez vous ?","bouton":"Demander une intervention","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."}]'::jsonb) where path = '/expertises/specialisations-constructeur/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"Un automaticien spécialisé SIEMENS affecté à temps plein, industrie près de Lyon","texte":"démarrage d''une nouvelle ligne de production, T2 et T3 2025","lienLibelle":"Étude de cas MERSEN : nouvelles lignes","lienHref":"/preuves/mersen/"},{"titre":"Maintenance d''un parc multimarques, pièces mécaniques de précision","texte":"centres d''usinage, presses et commandes numériques, un technicien intégré à temps plein en 2025","lienLibelle":"Étude de cas VOIT : site du Grand Est","lienHref":"/preuves/voit-grand-est/"},{"titre":"Installation et mise en production d''un parc machine neuf, site automobile","texte":"six techniciens aux compétences variées, mécanique, électricité et automatisme, depuis janvier 2023","lienLibelle":"Étude de cas EATON : mise en production","lienHref":"/preuves/eaton-mise-en-production/"},{"titre":"Montage aux standards d''un constructeur d''équipements, partout en France","texte":"techniciens formés aux équipements du fabricant, raccordements mécaniques et électriques compris","lienLibelle":"Étude de cas ORTHUS x WASHTEC : installation de stations","lienHref":"/preuves/orthus-washtec/"},{"titre":"Contrôle de chantier sur des projets d''automatisation logistique","texte":"plusieurs intervenants intégrés aux équipes, systèmes automatisés en aéroport, logistique et industrie","lienLibelle":"Étude de cas ALSTEF Group : collaboration","lienHref":"/preuves/alstef-group/"}]},{"type":"objections","questions":[{"question":"Notre parc mélange plusieurs marques. Vous couvrez tout ?","reponse":"C''est le cas le plus fréquent, et c''est la raison d''être de cette page. Nous couvrons Siemens, Schneider Electric, les gammes Allen Bradley rencontrées chez nos clients, la robotique industrielle, les machines spéciales et la commande numérique. Décrivez votre parc au téléphone : nous vous disons quelles marques nous prenons en propre et lesquelles demandent un spécialiste supplémentaire. Vous n''avez pas à multiplier les prestataires pour un seul atelier."},{"question":"Pouvez-vous reprendre un programme écrit par un autre prestataire ?","reponse":"Oui, c''est un cas très fréquent. Nous auditons l''existant, nous le documentons, puis nous le modifions proprement. Vous reprenez la main sur votre installation, avec une sauvegarde à jour. Vos codes restent votre propriété, la confidentialité figure au contrat."},{"question":"Intervenez-vous sur des automates anciens ou obsolètes ?","reponse":"Oui. Nos équipes savent utiliser les ateliers logiciels de chaque marque, y compris les versions anciennes encore en service dans l''industrie française. Nous maintenons l''existant tant que c''est raisonnable, et nous chiffrons la migration en parallèle : étude, conception, reprogrammation, essais. Vous décidez avec les coûts sous les yeux. Un automate annoncé en fin de vie se remplace en projet, pas en urgence."},{"question":"Qui intervient réellement sur nos machines ?","reponse":"Des techniciens salariés de Migen, évalués en entretien technique et comportemental, 10 % des candidats retenus. Leurs habilitations électriques sont à jour pour la consignation, la mesure sous tension et l''intervention en armoire. Nous n''envoyons jamais une sortie d''école seule sur un site que personne ne connaît. L''autonomie se vérifie avant, pas chez vous."},{"question":"Combien coûte l''intervention d''un automaticien ?","reponse":"Cela dépend du défaut, de l''équipement et de l''urgence. Le devis est chiffré au cas par cas, sans coefficient caché. Nous qualifions le besoin au téléphone, gratuitement, avant de chiffrer quoi que ce soit. Comparez toujours ce montant à celui d''une seule journée de ligne figée."},{"question":"Couvrez-vous notre région ?","reponse":"Oui. Quatre agences, Lyon en siège, Montréal, Dubaï et Madrid, et dix hubs de techniciens à Paris, Lille, Marseille, Toulouse, Lyon, Metz, Strasbourg, Bordeaux, Dijon et Nantes. Hors de ces villes, nos techniciens se déplacent : l''intervention n''est pas conditionnée à un hub à côté de votre site. Pour mettre un parc entier sous suivi, l''abonnement [Zéro arrêt](/offres/zero-arret/) propose trois niveaux de couverture, chiffrés sur devis."}]},{"type":"ctaFinal","question":"Besoin de sauvegarder vos automatismes avant la prochaine carte qui lâche ?","bouton":"Demander une intervention"}]'::jsonb) where path = '/expertises/specialisations-constructeur/';
